package service

import "github.com/mark3labs/mcp-go/mcp"

// ToolDefinitions is the single discoverable contract for remote clients.
func ToolDefinitions() []mcp.Tool {
	makeTool := func(name, description string, fields ...string) mcp.Tool {
		opts := []mcp.ToolOption{mcp.WithDescription(description)}
		for _, f := range fields {
			opts = append(opts, mcp.WithString(f, mcp.Required()))
		}
		return mcp.NewTool(name, opts...)
	}
	tools := []mcp.Tool{
		mcp.NewTool("stat", mcp.WithDescription("Read authorized metadata using file_id with optional version_id, or a pinned ref. Workspace grants reject mixed selectors and staging; pinned versions are never replaced with the current version."), mcp.WithString("file_id"), mcp.WithString("version_id"), mcp.WithString("ref")),
		makeTool("capabilities", "Discover currently authorized actions and HTTP recovery contracts. Read-only; does not probe providers or enable permissions."),
		mcp.NewTool("create_upload", mcp.WithDescription("Reserve a scoped upload; send raw parts over authenticated HTTP, never MCP base64. Common errors: invalid_upload, quota_exceeded, storage_disconnected, idempotency_conflict, service_admission_required."), mcp.WithString("space_id", mcp.Required()), mcp.WithString("path", mcp.Required()), mcp.WithNumber("size_bytes", mcp.Required()), mcp.WithString("sha256", mcp.Required()), mcp.WithString("idempotency_key", mcp.Required()), mcp.WithString("file_id"), mcp.WithString("expected_version"), mcp.WithString("caller"), mcp.WithString("task_ref"), mcp.WithString("entitlement_id")),
		makeTool("complete_upload", "Verify and commit the original upload. Replays return the same version.", "operation_id"),
		mcp.NewTool("input.bind_reference", mcp.WithDescription("Bind one owned file version to a consumer and project for private handoff; no URL is returned."), mcp.WithString("ref", mcp.Required()), mcp.WithString("consumer", mcp.Required()), mcp.WithString("project_ref", mcp.Required()), mcp.WithString("purpose", mcp.Required()), mcp.WithString("expected_sha256", mcp.Required()), mcp.WithString("idempotency_key", mcp.Required()), mcp.WithString("binding_id", mcp.Description("Existing owner-created receiver binding; cannot create or expand access.")), mcp.WithString("consumer_request_ref", mcp.Description("Original durable input ID; supply with request_expires_at for renewal.")), mcp.WithString("request_expires_at", mcp.Description("RFC3339 original input expiry; renewal cannot extend it."))),
		makeTool("input.handoff_status", "Inspect the original grant, expiry and cancellation before acquiring bytes or retrying.", "grant_id"),
		makeTool("input.handoff_renew", "Renew only the original bound receiver grant within its original input expiry; never creates input or permissions.", "grant_id"),
		makeTool("input.handoff_cancel", "Cancel the original grant; retain existing imported copies.", "grant_id"),
		mcp.NewTool("capability_check", mcp.WithDescription("Read-only preflight for one action in one space: reports implemented/configured/authorized facts, dependency observation and a safe recovery pointer. Never probes connections, changes permissions or scans directories. Unknown actions return unsupported_action."), mcp.WithString("action", mcp.Required()), mcp.WithString("space_id", mcp.Required()), mcp.WithString("ref", mcp.Description("Optional drivebridge:// pinned file reference narrowing the check to one file"))),
		mcp.NewTool("upload_batch_create", mcp.WithDescription("Open one folder-upload batch enumeration under a durable idempotency key; a lost creation response replays onto the same batch via operation_lookup. Bytes never flow through MCP."), mcp.WithString("space_id", mcp.Required()), mcp.WithString("conflict_policy", mcp.Description("fail (default), keep_both or new_version")), mcp.WithString("idempotency_key", mcp.Required())),
		mcp.NewTool("upload_batch_add_items", mcp.WithDescription("Append one enumeration page (1-500 entries) of relative paths and source fingerprints; empty directories are explicit is_dir entries. Common errors: invalid_request, operation_closed."), mcp.WithString("batch_id", mcp.Required()), mcp.WithArray("items", mcp.Required(), mcp.Description("Entries: relative_path required, size_bytes, sha256, optional file_id/expected_version for new_version, is_dir for empty directories."), mcp.Items(map[string]any{
			"type": "object",
			"properties": map[string]any{
				"relative_path":    map[string]any{"type": "string", "description": "Relative path inside the space; no absolute paths or parent traversal"},
				"is_dir":           map[string]any{"type": "boolean", "description": "Explicit empty-directory entry"},
				"size_bytes":       map[string]any{"type": "number", "description": "Plaintext size"},
				"sha256":           map[string]any{"type": "string", "description": "Source fingerprint"},
				"file_id":          map[string]any{"type": "string", "description": "new_version policy target file"},
				"expected_version": map[string]any{"type": "string", "description": "Pinned version for the new_version policy"},
			},
		}))),
		mcp.NewTool("upload_batch_seal", mcp.WithDescription("End the enumeration and freeze the batch fingerprint; items become schedulable through the scoped upload contract with batch_id+item_key."), mcp.WithString("batch_id", mcp.Required())),
		mcp.NewTool("upload_batch_get", mcp.WithDescription("Read one batch with a keyset item page (limit 1-200, default 50) reporting per-item status and the original operation ids."), mcp.WithString("batch_id", mcp.Required()), mcp.WithString("cursor"), mcp.WithString("limit")),
		mcp.NewTool("upload_batch_pause", mcp.WithDescription("Pause the original batch: new scheduling stops, verified data is kept."), mcp.WithString("batch_id", mcp.Required())),
		mcp.NewTool("upload_batch_resume", mcp.WithDescription("Resume the original batch after a pause."), mcp.WithString("batch_id", mcp.Required())),
		mcp.NewTool("upload_batch_cancel", mcp.WithDescription("Cancel the original batch; committed files stay as completed side effects and are never claimed as rolled back."), mcp.WithString("batch_id", mcp.Required())),
		mcp.NewTool("operation_lookup", mcp.WithDescription("Recover the original identity behind an idempotency key after a lost creation response; the server recomputes the fingerprint from the original request. Same key with a different fingerprint returns idempotency_conflict."), mcp.WithString("action", mcp.Required()), mcp.WithString("idempotency_key", mcp.Required()), mcp.WithObject("original_request", mcp.Required(), mcp.Description("The same business inputs as the original creation; never credentials."))),
		mcp.NewTool("upload_session", mcp.WithDescription("Read the durable transfer session of one upload operation: part size, verified received parts, durability and source_reselection_required."), mcp.WithString("operation_id", mcp.Required())),
		mcp.NewTool("retention_hold", mcp.WithDescription("Protect one file version against purge for a stated purpose until a fixed expiry. The source must be a share or operation the caller manages. Never a permanent-storage promise; purge execution is human-only and no agent purge tool exists."), mcp.WithString("file_id", mcp.Required()), mcp.WithString("version_id"), mcp.WithString("purpose", mcp.Required()), mcp.WithString("source_ref", mcp.Required()), mcp.WithString("expires_at", mcp.Required()), mcp.WithString("idempotency_key", mcp.Required())),
		mcp.NewTool("retention_hold_get", mcp.WithDescription("Read one retention hold with its current protection verdict and safe source facts."), mcp.WithString("hold_id", mcp.Required())),
		mcp.NewTool("file_threads_list", mcp.WithDescription("List discussion threads on one file with their plain-text messages; anchored version state is reported without re-anchoring."), mcp.WithString("file_id", mcp.Required()), mcp.WithString("cursor"), mcp.WithString("limit")),
		mcp.NewTool("file_thread_create", mcp.WithDescription("Open one discussion thread on a file (file-level by default, or an explicit version anchor). Body is plain text up to 10000 characters."), mcp.WithString("file_id", mcp.Required()), mcp.WithString("version_id"), mcp.WithString("body", mcp.Required()), mcp.WithString("idempotency_key", mcp.Required())),
		mcp.NewTool("thread_reply", mcp.WithDescription("Append one plain-text reply under a durable idempotency key."), mcp.WithString("thread_id", mcp.Required()), mcp.WithString("body", mcp.Required()), mcp.WithString("idempotency_key", mcp.Required())),
		mcp.NewTool("thread_message_edit", mcp.WithDescription("Edit the caller's own message under an optimistic revision check; a stale revision keeps the server body and the client draft (revision_conflict)."), mcp.WithString("message_id", mcp.Required()), mcp.WithString("body", mcp.Required()), mcp.WithString("expected_revision", mcp.Required())),
		mcp.NewTool("thread_message_delete", mcp.WithDescription("Replace the caller's own message with an audit placeholder under an optimistic revision check."), mcp.WithString("message_id", mcp.Required()), mcp.WithString("expected_revision", mcp.Required())),
		mcp.NewTool("thread_resolve", mcp.WithDescription("Resolve a thread. Only the thread state changes; domain review facts are independent."), mcp.WithString("thread_id", mcp.Required())),
		mcp.NewTool("thread_reopen", mcp.WithDescription("Reopen a resolved thread."), mcp.WithString("thread_id", mcp.Required())),
		mcp.NewTool("private_note_get", mcp.WithDescription("Read the caller's own private note on one file; only the author row exists and only with current file permission."), mcp.WithString("file_id", mcp.Required())),
		mcp.NewTool("private_note_set", mcp.WithDescription("Write the caller's own private note under an optimistic revision check."), mcp.WithString("file_id", mcp.Required()), mcp.WithString("body", mcp.Required()), mcp.WithString("expected_revision")),
		mcp.NewTool("private_note_publish_preview", mcp.WithDescription("Preview what publishing the private note as a team thread would create. Writes nothing; publication is an explicit file_thread_create."), mcp.WithString("file_id", mcp.Required())),
		mcp.NewTool("retention_preview", mcp.WithDescription("Build a read-only cleanup preview (trash or historical_versions category) under the current policy revision. Preview only; execution re-validates holds, references and permissions and is not an agent action."), mcp.WithString("category", mcp.Required())),
		mcp.NewTool("changes_v2", mcp.WithDescription("Read one bounded page of committed file change events inside the authorized scope: opaque owner-bound cursor (expired means a controlled snapshot rebuild), safe references only, at-least-once delivery deduplicated by event_id by consumers."), mcp.WithString("space_id"), mcp.WithString("cursor"), mcp.WithString("limit")),
		mcp.NewTool("change_subscription_create", mcp.WithDescription("Register one authenticated polling consumer inside an authorized scope; subscriptions never enable whole-space automation by themselves."), mcp.WithString("consumer_id", mcp.Required()), mcp.WithString("space_id", mcp.Required())),
		mcp.NewTool("change_subscription_ack", mcp.WithDescription("Advance the subscription checkpoint to a delivered sequence; monotonic and never ahead of delivery (ack_ahead)."), mcp.WithString("subscription_id", mcp.Required()), mcp.WithString("checkpoint", mcp.Required())),
		mcp.NewTool("automation_intent_get", mcp.WithDescription("Read one automation intent with its original rule, event and operation references and pause reason."), mcp.WithString("intent_id", mcp.Required())),
		mcp.NewTool("organize_plan", mcp.WithDescription("Freeze one organization plan from an exact fixed collection (snapshot or explicit refs) with typed actions under a durable idempotency key. Unmatched pre-authorization leaves approval_required; semantic Top-K is never executable as a whole."), mcp.WithString("source_snapshot_id"), mcp.WithArray("refs"), mcp.WithArray("actions", mcp.Required()), mcp.WithString("policy_id"), mcp.WithString("idempotency_key", mcp.Required())),
		mcp.NewTool("organize_plan_get", mcp.WithDescription("Read one organization plan: revision, paged per-item impacts, risk, missing permissions and waiting reasons."), mcp.WithString("plan_id", mcp.Required()), mcp.WithString("cursor"), mcp.WithString("limit")),
		mcp.NewTool("organize_apply", mcp.WithDescription("Execute one plan under its expected_revision: only a human confirmation or a currently valid pre-authorization opens execution; every item write re-checks permission, source version and policy; drift marks that item stale."), mcp.WithString("plan_id", mcp.Required()), mcp.WithString("expected_revision", mcp.Required())),
		mcp.NewTool("organize_compensation_plan", mcp.WithDescription("Derive the reverse plan from a completed run's recorded results under a durable idempotency key; it never executes immediately and later target changes surface as compensation_conflict."), mcp.WithString("plan_id", mcp.Required()), mcp.WithString("idempotency_key", mcp.Required())),
		mcp.NewTool("delivery_prepare", mcp.WithDescription("Freeze one fixed delivery manifest from a collection snapshot under the caller's share management permission and a durable idempotency key. Members and versions freeze; incomplete stays incomplete."), mcp.WithString("share_id", mcp.Required()), mcp.WithString("snapshot_id", mcp.Required()), mcp.WithString("expected_share_revision"), mcp.WithString("idempotency_key", mcp.Required())),
		mcp.NewTool("delivery_get", mcp.WithDescription("Read one delivery manifest revision with per-item readability, verification and retention facts."), mcp.WithString("share_id", mcp.Required()), mcp.WithString("manifest_revision", mcp.Required())),
		mcp.NewTool("delivery_receipt", mcp.WithDescription("Record one delivery fact on a published manifest. Anonymous share access carries server-observed facts only; verified confirmations need an authenticated receiver."), mcp.WithString("share_id", mcp.Required()), mcp.WithString("manifest_revision", mcp.Required()), mcp.WithString("kind", mcp.Required()), mcp.WithString("digest"), mcp.WithString("note")),
		mcp.NewTool("content_bindings_list", mcp.WithDescription("List content bindings in one space with their state and the original owner recovery ref."), mcp.WithString("space_id", mcp.Required())),
		mcp.NewTool("content_binding_create", mcp.WithDescription("Pin one fixed version to a content-owner project for a stated purpose under a durable idempotency key. Requires an enabled human-configured content policy; nothing is processed at binding time."), mcp.WithString("ref", mcp.Required()), mcp.WithString("manju_connection_id", mcp.Required()), mcp.WithString("project_ref", mcp.Required()), mcp.WithString("purpose", mcp.Required()), mcp.WithString("idempotency_key", mcp.Required())),
		mcp.NewTool("content_binding_get", mcp.WithDescription("Read one binding's state, index generation and original recovery link."), mcp.WithString("binding_id", mcp.Required())),
		mcp.NewTool("content_process", mcp.WithDescription("Submit one bound version to the content owner under the approved policy revision and an idempotency key. Failures never affect the original file; late results never attach to a newer version."), mcp.WithString("binding_id", mcp.Required()), mcp.WithString("policy_revision", mcp.Required()), mcp.WithString("idempotency_key", mcp.Required())),
		mcp.NewTool("content_query", mcp.WithDescription("Run one typed retrieval query: exact mode reads managed facts; discovery mode asks the content owner with evidence/locators and re-authorizes every item. Pure queries never trigger new analysis."), mcp.WithString("mode", mcp.Required()), mcp.WithString("text"), mcp.WithString("image_ref"), mcp.WithArray("space_ids", mcp.Required()), mcp.WithArray("modalities"), mcp.WithString("evidence_required"), mcp.WithNumber("limit"), mcp.WithString("manju_connection_id")),
		mcp.NewTool("analytics_query", mcp.WithDescription("Run one typed analytical query over authorized data: fixed datasets (file_current/transfer_facts/audit_facts/capacity_daily), closed field/metric vocabularies, dimensions<=3, limit<=200, consistency live|observed (observed requires the analytics backend; unavailability is reported honestly). Results carry coverage/partial/missing facts and never authorize deletions."), mcp.WithString("dataset", mcp.Required()), mcp.WithArray("filters"), mcp.WithArray("dimensions"), mcp.WithArray("metrics"), mcp.WithString("consistency"), mcp.WithNumber("limit"), mcp.WithString("cursor")),
		mcp.NewTool("analytics_query_get", mcp.WithDescription("Read one analytical query job by id; ids carry no permissions."), mcp.WithString("query_id", mcp.Required())),
		mcp.NewTool("analytics_snapshot", mcp.WithDescription("Create one service-generated analytical snapshot export under a durable idempotency key (human export authorization; agents are refused). The manifest carries schema/generation/watermarks/fields/digest; no credentials, temporary URLs or file bodies."), mcp.WithString("dataset", mcp.Required()), mcp.WithArray("filters"), mcp.WithArray("fields"), mcp.WithString("idempotency_key", mcp.Required())),
		mcp.NewTool("analytics_snapshot_query", mcp.WithDescription("Run one typed query against a snapshot through the fixed analytical engine; a missing engine reports analytics_backend_unavailable and typed validation still rejects SQL or path payloads first."), mcp.WithString("snapshot_id", mcp.Required()), mcp.WithString("dataset", mcp.Required()), mcp.WithArray("filters"), mcp.WithArray("dimensions"), mcp.WithArray("metrics")),
		mcp.NewTool("transfer_plan", mcp.WithDescription("Freeze one cross-storage copy/migrate intent under a durable idempotency key: pinned source refs with digests, one target, conflict policy. Copying and source cleanup stay separate facts."), mcp.WithString("sources", mcp.Required()), mcp.WithString("target_space_id", mcp.Required()), mcp.WithString("target_path", mcp.Required()), mcp.WithString("mode"), mcp.WithString("conflict_policy"), mcp.WithString("cross_space_confirmed"), mcp.WithString("idempotency_key", mcp.Required())),
		mcp.NewTool("transfer_plan_get", mcp.WithDescription("Read one transfer plan with a paged item impact preview and its revision."), mcp.WithString("plan_id", mcp.Required()), mcp.WithString("cursor"), mcp.WithString("limit")),
		mcp.NewTool("transfer_execute", mcp.WithDescription("Execute the confirmed copy part of a plan under its expected_revision; per-item idempotency replays on the original operations and drifted sources pause only their item. Source cleanup is a separate human action with no agent tool."), mcp.WithString("plan_id", mcp.Required()), mcp.WithString("expected_revision", mcp.Required())),
		mcp.NewTool("files_query", mcp.WithDescription("Run one exact typed query over authorized managed files: closed filter vocabulary (mime_type, path_prefix, size_bytes, updated_at, caller, task_ref, trashed, labels.<namespace>), keyset pagination with limit<=200, opaque cursor bound to the query and catalogue revision (query_changed on mismatch). mode=duplicates groups only verified equal digests inside the readable scope and never authorizes deletion."), mcp.WithString("mode"), mcp.WithArray("space_ids", mcp.Required()), mcp.WithString("filters"), mcp.WithString("sort"), mcp.WithNumber("limit"), mcp.WithString("cursor")),
		mcp.NewTool("file_labels_set", mcp.WithDescription("Replace one namespace's labels on a file. Agents write suggested only; manual/rule attempts fail with label_namespace_forbidden and never overwrite human decisions."), mcp.WithString("file_id", mcp.Required()), mcp.WithString("namespace", mcp.Required()), mcp.WithArray("labels", mcp.Required()), mcp.WithString("expected_revision")),
		mcp.NewTool("file_collections_list", mcp.WithDescription("List the caller's collections in one space with revisions and member counts.")), mcp.NewTool("file_collection_create", mcp.WithDescription("Open one manual or rule collection under a durable idempotency key; rule collections store the exact versioned conditions."), mcp.WithString("space_id", mcp.Required()), mcp.WithString("name", mcp.Required()), mcp.WithString("kind", mcp.Required()), mcp.WithString("scope"), mcp.WithString("rule"), mcp.WithString("idempotency_key", mcp.Required())),
		mcp.NewTool("collection_members_set", mcp.WithDescription("Replace the explicit include/exclude member decisions under an optimistic revision check (collection_revision_conflict on stale writes)."), mcp.WithString("collection_id", mcp.Required()), mcp.WithString("expected_revision", mcp.Required()), mcp.WithString("include"), mcp.WithString("exclude")),
		mcp.NewTool("collection_snapshot", mcp.WithDescription("Freeze one collection read: entries pin the exact file/version captured now; snapshots grant no read permission and later reads re-authorize every entry."), mcp.WithString("collection_id", mcp.Required())),
		mcp.NewTool("saved_searches_list", mcp.WithDescription("List the caller's saved exact queries; stored queries carry no permissions and re-authorize at execution.")),
		mcp.NewTool("saved_search_create", mcp.WithDescription("Store one exact typed query by name for later re-execution."), mcp.WithString("name", mcp.Required()), mcp.WithString("query", mcp.Required())),
		mcp.NewTool("cloud_entries", mcp.WithDescription("List one bounded page of external entries under a bound cloud root. Observations are provider facts (version_strength observed_only); only an explicit import creates managed copies. Common errors: cursor_expired, source_changed, unsupported (capability not enabled)."), mcp.WithString("connection_id", mcp.Required()), mcp.WithString("root_id", mcp.Required()), mcp.WithString("parent_ref"), mcp.WithString("cursor"), mcp.WithString("limit")),
		mcp.NewTool("cloud_entry_stat", mcp.WithDescription("Check one external entry against the live provider under the current authorization; expected_revision mismatch is source_changed, never a silent refresh."), mcp.WithString("connection_id", mcp.Required()), mcp.WithString("entry_ref", mcp.Required()), mcp.WithString("expected_revision")),
		mcp.NewTool("cloud_changes", mcp.WithDescription("Advance one root's provider change feed. Providers without a native cursor return unsupported; change detection there is a budgeted cloud_scan."), mcp.WithString("connection_id", mcp.Required()), mcp.WithString("root_id", mcp.Required()), mcp.WithString("cursor"), mcp.WithString("limit")),
		mcp.NewTool("cloud_scan", mcp.WithDescription("Run one budgeted enumeration of a bound root under a durable idempotency key. Partial scans never derive deletions; only complete scans tombstone confirmed-absent entries. Returns the original Operation-scoped scan facts."), mcp.WithString("connection_id", mcp.Required()), mcp.WithString("root_id", mcp.Required()), mcp.WithString("budget"), mcp.WithString("idempotency_key", mcp.Required())),
		mcp.NewTool("search", mcp.WithDescription("Search authorized managed files; after is RFC3339, MIME is exact."), mcp.WithString("space_id", mcp.Required()), mcp.WithString("query", mcp.Required()), mcp.WithString("path"), mcp.WithString("mime_type"), mcp.WithString("after")),
		mcp.NewTool("trash", mcp.WithDescription("Move an authorized file to trash; no permanent deletion. Common errors: file_trashed (already trashed), not_found."), mcp.WithString("file_id"), mcp.WithString("ref", mcp.Description("drivebridge://<instance>/file/<id>/version/<version> alternative to file_id"))),
		mcp.NewTool("restore", mcp.WithDescription("Restore an authorized trashed file. Common errors: file_not_trashed, not_found."), mcp.WithString("file_id"), mcp.WithString("ref", mcp.Description("drivebridge://<instance>/file/<id>/version/<version> alternative to file_id"))),
		makeTool("spaces", "List the caller's allowed spaces."),
		makeTool("files", "List allowed files in one space.", "space_id"),
		mcp.NewTool("prepare_reference", mcp.WithDescription("Return a pinned reference without a URL. Authorized hosts acquire temporary read access over HTTP immediately before submission. Rejected for encrypted spaces, whose acquisition only runs through the server decryption stream."), mcp.WithString("file_id"), mcp.WithString("version_id"), mcp.WithString("ref")),
		makeTool("operations", "List allowed transfer operations."),
		mcp.NewTool("inbox", mcp.WithDescription("List the caller's recent authorized operation results (30 days)."), mcp.WithString("status"), mcp.WithString("caller"), mcp.WithString("space_id")),
		mcp.NewTool("archive", mcp.WithDescription("Copy one pinned version into a managed destination; never replaces an existing file. Common errors: unsupported (non-managed destination), version_conflict, invalid_archive."), mcp.WithString("source_file_id", mcp.Required()), mcp.WithString("source_version_id", mcp.Required()), mcp.WithString("target_space_id", mcp.Required()), mcp.WithString("target_path", mcp.Required()), mcp.WithString("idempotency_key", mcp.Required())),
		makeTool("operation_get", "Recover an existing operation and its received parts.", "operation_id"),
		makeTool("resume", "Resume the original operation; never generates content.", "operation_id"),
		makeTool("cancel", "Cancel the original file transfer.", "operation_id"),
		mcp.NewTool("users_create", mcp.WithDescription("Batch-provision key users; admin user key only. Plaintext keys appear exactly once in the issuance result."), mcp.WithArray("users", mcp.Required(), mcp.Description("Batch entries: name required, optional operator-supplied key, days lifetime, admin flag."), mcp.Items(map[string]any{
			"type": "object",
			"properties": map[string]any{
				"name":  map[string]any{"type": "string", "description": "Display name (1-120 chars)"},
				"key":   map[string]any{"type": "string", "description": "Operator-supplied pre-generated key (32-128 printable ASCII chars, any prefix); empty generates one"},
				"days":  map[string]any{"type": "number", "description": "Optional lifetime in days; zero never expires"},
				"admin": map[string]any{"type": "boolean", "description": "Whether the key may provision users"},
			},
		}))),
		makeTool("users_list", "List user keys with lifecycle metadata only; no hashes. Admin user key only."),
		makeTool("users_revoke", "Revoke a user key by id; the next request is unauthorized. Admin user key only.", "key_id"),
	}
	insightFields := [][2]string{
		{"space_id", "Restrict the projection to one space"},
		{"connection_id", "Restrict the projection to one storage connection"},
		{"from", "First UTC date YYYY-MM-DD (default last 30 days)"},
		{"to", "Last UTC date YYYY-MM-DD"},
		{"actor", "Authenticated actor filter"},
		{"caller", "Declared caller label filter"},
		{"direction", "Observed transfer direction filter"},
		{"purpose", "Transfer purpose filter"},
		{"group", "usage_breakdown grouping: space, connection, actor, caller, direction, purpose"},
		{"action", "audit_events action filter"},
		{"outcome", "audit_events outcome filter"},
	}
	for _, name := range []string{"usage_summary", "usage_series", "usage_breakdown", "usage_scans", "audit_events"} {
		opts := []mcp.ToolOption{mcp.WithDescription("Read authorized usage/audit projections; byte counters are not provider billing. Projections read what was observed; missing data is not zero.")}
		for _, field := range insightFields {
			opts = append(opts, mcp.WithString(field[0], mcp.Description(field[1])))
		}
		tools = append(tools, mcp.NewTool(name, opts...))
	}
	tools = append(tools, mcp.NewTool("usage_scan", mcp.WithDescription("Run an already-enabled inventory within its existing budget. Requires full-space read scope; cannot enable scanning or change permissions."), mcp.WithString("space_id", mcp.Required()), mcp.WithString("resume_id")))
	for i := range tools {
		mcp.WithString("tenant_context", mcp.Description("Optional tenant ID; the service validates membership. Agent credentials remain pinned to their original tenant."))(&tools[i])
		mcp.WithString("space_context", mcp.Description("Optional selected data space; never grants access by itself. approval_required means a human must use the service authorization center."))(&tools[i])
	}
	return tools
}
